import java.awt.*;import java.applet.*; public class DrawShapes extends Applet {Font font;Color gray,white,black;public void init(){font=new Font("Arial",Font.ITALIC,18);gray=Color.gray;white=Color.white;black=Color.black;setBackground(white);}public void paint(Graphics g){g.setFont(font);g.drawString("Draw Shapes",90,20);g.setColor(black);g.drawRect(120,120,120,120);g.setColor(gray);g.fillRect(115,115,90,90);g.setColor(black);g.fillArc(110,110,50,50,0,360);g.setColor(gray);g.drawRect(50,50,50,50);g.fillRect(50,50,60,60);}}
